export const BUDGET=240;
export function rng(seed){return()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
export const neighbors=p=>[p%10<9?p+1:-1,p<90?p+10:-1,p%10>0?p-1:-1,p>=10?p-10:-1];
const h=p=>18-p%10-Math.floor(p/10);
export function mapFor(seed){const r=rng(seed);for(let attempt=0;attempt<1000;attempt++){let walls=Array.from({length:100},(_,i)=>i!==0&&i!==99&&r()<.25);let q=[0],seen=new Set(q);for(let j=0;j<q.length;j++)for(const n of neighbors(q[j]))if(n>=0&&!walls[n]&&!seen.has(n)){seen.add(n);q.push(n)}if(seen.has(99)){let rewards=new Set;while(rewards.size<4){let n=1+Math.floor(r()*98);if(!walls[n])rewards.add(n)}return{walls,rewards}}}throw Error('Map generation failed')}
export function search(map,cfg){let open=[{p:0,g:0,path:[0]}],best=new Map([[0,0]]),cost=0,trace=[0];while(open.length&&cost+4<=BUDGET){open.sort((a,b)=>score(a)-score(b));let x=open.shift();if(x.g!==best.get(x.p))continue;trace=x.path;if(x.p===99)return{path:trace,cost,success:true};if(x.g>=cfg.depth)continue;cost+=4;for(const n of neighbors(x.p)){if(n<0||map.walls[n])continue;let g=x.g+1;if(g>=(best.get(n)??Infinity))continue;best.set(n,g);open.push({p:n,g,path:[...x.path,n]})}}const goal=open.find(x=>x.p===99);return{path:goal?goal.path:trace,cost,success:!!goal};function score(x){return cfg.kind==='bfs'?x.g:cfg.kind==='greedy'?h(x.p):x.g+cfg.weight*h(x.p)}}
function state(map,p){return `${Math.sign(9-p%10)},${Math.sign(9-Math.floor(p/10))}:`+neighbors(p).map(n=>n<0||map.walls[n]?1:0).join('')}
export function policy(map,Q,{train=false,random=rng(1),epsilon=.15}={}){let p=0,path=[0],cost=0,collected=new Set;for(let step=0;step<60;step++){let key=state(map,p),values=Q[key]||[0,0,0,0],ns=neighbors(p);cost+=4;let allowed=ns.map((n,i)=>n>=0&&!map.walls[n]?i:-1).filter(i=>i>=0);if(!allowed.length)break;let a=train&&random()<epsilon?allowed[Math.floor(random()*allowed.length)]:allowed.reduce((a,b)=>values[b]>values[a]?b:a);let next=ns[a];let reward=next===99?30:-1;if(map.rewards.has(next)&&!collected.has(next)){reward+=2;collected.add(next)}if(train){Q[key]??=[0,0,0,0];let nextValues=Q[state(map,next)]||[0,0,0,0],legal=neighbors(next).map((n,i)=>n>=0&&!map.walls[n]?nextValues[i]:-Infinity);let future=next===99?0:Math.max(...legal);Q[key][a]+=.18*(reward+.94*future-Q[key][a])}p=next;path.push(p);if(p===99)return{path,cost,success:true}}return{path,cost,success:false}}
export const fixed={kind:'greedy',weight:2,depth:24};
export const candidates=[...['greedy','bfs'].flatMap(kind=>[24,40,60].map(depth=>({kind,weight:1,depth}))),...[1,1.25,1.5,2,3].flatMap(weight=>[24,40,60].map(depth=>({kind:'astar',weight,depth})))];
export function evaluate(maps,fn){let wins=0,steps=0,cost=0;for(const m of maps){const x=fn(m);if(x.success){wins++;steps+=x.path.length-1}cost+=x.cost}return{rate:wins/maps.length*100,avg:wins?steps/wins:null,cost:cost/maps.length,score:wins*1000-steps/(wins||1)}}
